/// <summary>
/// Update all transfer sites
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_inventSiteId">InventSiteId</param>
/// <param name = "_status">METItemStatus</param>
public void updateItemStatusOfTransferSite(ItemId _itemId, InventSiteId _inventSiteId, METItemStatus _status)
{       
    if (!_itemId || !_inventSiteId)
    {
        return;
    }
    Set transferredSites = new Set(Types::String);
    Set visitedSites = new Set(Types::String);
    container toVisit;

    InventParameters inventParameters = InventParameters::find();

    toVisit = [_inventSiteId];

    for (int i = 1; i<= conLen(toVisit); i++)
    {
        str currentSite = conPeek(toVisit, i);

        // Skip if already visited
        if (visitedSites.in(currentSite))
        {
            continue;
        }

        visitedSites.add(currentSite);

        METReqItemTableInventDimView metReqItemTableInventDimView;
        METItemStatusWarehouses metItemStatusWarehouses;

        while select metReqItemTableInventDimView
        where metReqItemTableInventDimView.ItemId == _itemId
        && metReqItemTableInventDimView.InventSiteId != currentSite
        && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer
        && metReqItemTableInventDimView.MainWarehouseInventSiteId == currentSite
        notexists join metItemStatusWarehouses
        where metItemStatusWarehouses.InventLocationId == metReqItemTableInventDimView.InventLocationId
        {
            if (!transferredSites.in(metReqItemTableInventDimView.InventSiteId))
            {
                transferredSites.add( metReqItemTableInventDimView.InventSiteId);
                toVisit += metReqItemTableInventDimView.InventSiteId; // Enqueue next site

                if (metReqItemTableInventDimView) // Activate Item Status
                {
                    if (_status == METConstants::Active)
                    {
                        this.updateInsertStatusToActive(metReqItemTableInventDimView);
                    }
                    else if (_status == METConstants::NewStr)
                    {
                        this.updateInsertStatusToNew(metReqItemTableInventDimView);
                    }
                }                                        
            }
        }
    }
}

public void updateInsertStatusToActive(METReqItemTableInventDimView _metReqItemTableInventDimView)
{
    METInventItemOrderSetup metInventItemOrderSetup = METInventItemOrderSetup::findByItemAndSite(_metReqItemTableInventDimView.ItemId, _metReqItemTableInventDimView.InventSiteId, true);

    if (!metInventItemOrderSetup)
    {
        METInventItemOrderSetup metInventItemOrderSetupLocal;
        InventItemPurchSetup inventItemPurchSetupLocal;
        InventDim inventDimLocal;

        select firstonly InventDimId from inventItemPurchSetupLocal
            exists join inventDimLocal
            where inventDimLocal.InventSiteId == _metReqItemTableInventDimView.InventSiteId
            && inventItemPurchSetupLocal.ItemId ==  metInventItemOrderSetup.ItemId
            && inventDimLocal.inventDimId == inventItemPurchSetupLocal.InventDimId;

        metInventItemOrderSetupLocal.ItemId = metInventItemOrderSetup.ItemId;
        metInventItemOrderSetupLocal.InventDimId = inventItemPurchSetupLocal.InventDimId;
        metInventItemOrderSetupLocal.SiteId = _metReqItemTableInventDimView.InventSiteId;
        metInventItemOrderSetupLocal.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus;
        metInventItemOrderSetupLocal.PublishPriceBook  = true;
        metInventItemOrderSetupLocal.PublishPortal = true;
        metInventItemOrderSetupLocal.PublishHost = true;
        metInventItemOrderSetupLocal.insert();
    }
    else
    {
        metInventItemOrderSetup.ItemStatus          = METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus;
        metInventItemOrderSetup.PublishPriceBook    = true;
        metInventItemOrderSetup.PublishPortal       = true;
        metInventItemOrderSetup.PublishHost         = true;
        metInventItemOrderSetup.update();
    }
}

public void updateInsertStatusToNew(METReqItemTableInventDimView _metReqItemTableInventDimView)
{
    METInventItemOrderSetup metInventItemOrderSetup = METInventItemOrderSetup::findByItemAndSite(_metReqItemTableInventDimView.ItemId, _metReqItemTableInventDimView.InventSiteId, true);

    if (!metInventItemOrderSetup)
    {
        METInventItemOrderSetup metInventItemOrderSetupLocal;
        InventItemPurchSetup inventItemPurchSetupLocal;
        InventDim inventDimLocal;

        select firstonly InventDimId from inventItemPurchSetupLocal
            exists join inventDimLocal
            where inventDimLocal.InventSiteId == _metReqItemTableInventDimView.InventSiteId
            && inventItemPurchSetupLocal.ItemId ==  metInventItemOrderSetup.ItemId
            && inventDimLocal.inventDimId == inventItemPurchSetupLocal.InventDimId;

        metInventItemOrderSetupLocal.ItemId = metInventItemOrderSetup.ItemId;
        metInventItemOrderSetupLocal.InventDimId = inventItemPurchSetupLocal.InventDimId;
        metInventItemOrderSetupLocal.SiteId = _metReqItemTableInventDimView.InventSiteId;
        metInventItemOrderSetupLocal.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus;
        metInventItemOrderSetupLocal.insert();
    }
    else
    {
        metInventItemOrderSetup.ItemStatus          = METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus;
        metInventItemOrderSetup.PublishPriceBook    = false;
        metInventItemOrderSetup.PublishPortal       = false;
        metInventItemOrderSetup.PublishHost         = false;
        metInventItemOrderSetup.update();
    }
}

/// <summary>
/// Update all transfer sites
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_inventSiteId">InventSiteId</param>
/// <param name = "_status">METItemStatus</param>
public static void runItemStatusDeleteJob(ItemId _itemId, InventSiteId _inventSiteId)
{
    if (!_itemId || !_inventSiteId)
    {
        return;
    }
    Set transferredSites = new Set(Types::String);
    Set visitedSites = new Set(Types::String);
    container toVisit;

    InventParameters inventParameters = InventParameters::find();

    toVisit = [_inventSiteId];

    for (int i = 1; i<= conLen(toVisit); i++)
    {
        str currentSite = conPeek(toVisit, i);

        // Skip if already visited
        if (visitedSites.in(currentSite))
        {
            continue;
        }

        visitedSites.add(currentSite);

        METReqItemTableInventDimView metReqItemTableInventDimView;
        METItemStatusWarehouses metItemStatusWarehouses;

        while select metReqItemTableInventDimView
        where metReqItemTableInventDimView.ItemId == _itemId
        && metReqItemTableInventDimView.InventSiteId != currentSite
        && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer
        && metReqItemTableInventDimView.MainWarehouseInventSiteId == currentSite
        notexists join metItemStatusWarehouses
        where metItemStatusWarehouses.InventLocationId == metReqItemTableInventDimView.InventLocationId
        {
            if (!transferredSites.in(metReqItemTableInventDimView.InventSiteId))
            {
                transferredSites.add( metReqItemTableInventDimView.InventSiteId);
                toVisit += metReqItemTableInventDimView.InventSiteId; // Enqueue next site

                if (metReqItemTableInventDimView) // Set Item Status
                {
                    //Call batch job
                    METChangeItemStatusController controller  = METChangeItemStatusController::construct();
                    METChangeItemStatusContract contract = controller ? controller.getDataContractObject() : null;
                    if (!contract)
                    {
                        throw error(Error::wrongUseOfFunction(funcName()));
                    }
                    // Set contract fields
                    contract.parmItemId(_itemId);
                    contract.parmInventSiteId(metReqItemTableInventDimView.InventSiteId);
                    contract.parmMETItemStatus(METConstants::Deleted);
                    //Set controller class method
                    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous); // Set execution mode
                    controller.parmShowDialog(false);
                    controller.parmLoadFromSysLastValue(false);
                    //controller.parmInBatch(true);
                    controller.parmDialogCaption(strFmt("%1 - %2 - %3 - %4", "@MET:ChangeItemStatus", _itemId, _inventSiteId, METConstants::Deleted));
                    controller.startOperation();
                }
            }
        }
    }
}
